VALUES ('ece67cfd-affb-536d-8107-e8ff01b7668f', '33210bed-c3f2-5e1b-8548-d67df4855a90', jsonb_build_object('es', $hope$Vida en equipo$hope$), jsonb_build_object('es', $hope$Comunicarse entre culturas, resolver conflictos, liderar sirviendo, poner límites y proteger a los más vulnerables.$hope$), 2)
